import Component from "@glimmer/component";

function convertToSeconds(time) {
  const match = time.toString().match(/(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?/);
  const [hours, minutes, seconds] = match.slice(1);

  if (hours || minutes || seconds) {
    const h = parseInt(hours, 10) || 0;
    const m = parseInt(minutes, 10) || 0;
    const s = parseInt(seconds, 10) || 0;

    return h * 3600 + m * 60 + s;
  }
  return time;
}

export default class LazyIframe extends Component {
  get iframeSrc() {
    switch (this.args.providerName) {
      case "youtube":
        let url = `https://www.youtube.com/embed/${this.args.videoId}?autoplay=1&rel=0`;
        if (this.args.listId) {
          url += `&list=${encodeURIComponent(this.args.listId)}`;
        }
        if (this.args.startTime) {
          url += `&start=${convertToSeconds(this.args.startTime)}`;
        }
        return url;
      case "vimeo":
        return `https://player.vimeo.com/video/${this.args.videoId}${
          this.args.videoId.includes("?") ? "&" : "?"
        }autoplay=1`;
      case "tiktok":
        return `https://www.tiktok.com/embed/v2/${this.args.videoId}`;
    }
  }

  <template>
    {{#if @providerName}}
      <iframe
        allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
        frameborder="0"
        scrolling="no"
        seamless="seamless"
        src={{this.iframeSrc}}
        title={{@title}}
      ></iframe>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { concat } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { trustHTML } from "@ember/template";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";
import LazyIframe from "./lazy-iframe.gjs";

export default class LazyVideo extends Component {
  @tracked isLoaded = false;

  get thumbnailStyle() {
    const color = this.args.videoAttributes.dominantColor;
    if (color?.match(/^[0-9A-Fa-f]+$/)) {
      return trustHTML(`background-color: #${color};`);
    }
  }

  @action
  loadEmbed() {
    if (!this.isLoaded) {
      this.isLoaded = true;
      this.args.onLoadedVideo?.();
    }
  }

  @action
  onKeyPress(event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.loadEmbed();
    }
  }

  <template>
    <div
      class={{dConcatClass
        "lazy-video-container"
        (concat @videoAttributes.providerName "-onebox")
        (if this.isLoaded "video-loaded")
      }}
      data-provider-name={{@videoAttributes.providerName}}
      data-video-id={{@videoAttributes.id}}
      data-video-list-id={{@videoAttributes.listId}}
      data-video-start-time={{@videoAttributes.startTime}}
      data-video-title={{@videoAttributes.title}}
    >
      {{#if this.isLoaded}}
        <LazyIframe
          @listId={{@videoAttributes.listId}}
          @providerName={{@videoAttributes.providerName}}
          @startTime={{@videoAttributes.startTime}}
          @title={{@videoAttributes.title}}
          @videoId={{@videoAttributes.id}}
        />
      {{else}}
        <div
          aria-label={{i18n
            "lazy_videos.play_video"
            title=@videoAttributes.title
          }}
          class={{dConcatClass "video-thumbnail" @videoAttributes.providerName}}
          role="button"
          style={{this.thumbnailStyle}}
          tabindex="0"
          {{on "click" this.loadEmbed}}
          {{on "keypress" this.onKeyPress}}
        >
          <img
            class={{concat @videoAttributes.providerName "-thumbnail"}}
            loading="lazy"
            src={{@videoAttributes.thumbnail}}
            title={{@videoAttributes.title}}
          />
          <div
            class={{dConcatClass
              "icon"
              (concat @videoAttributes.providerName "-icon")
            }}
          ></div>
        </div>
        <div class="title-container">
          <div class="title-wrapper">
            <a
              class="title-link"
              href={{@videoAttributes.url}}
              rel="noopener noreferrer"
              target="_blank"
              title={{@videoAttributes.title}}
            >
              {{@videoAttributes.title}}
            </a>
          </div>
        </div>
      {{/if}}
    </div>
  </template>
}
import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-lazy-videos";

export default {
  name: "lazy-videos-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.setAdminPluginIcon(PLUGIN_ID, "bed");
    });
  },
};
export default function getVideoAttributes(cooked) {
  if (!cooked.classList.contains("lazy-video-container")) {
    return {};
  }

  const url = cooked.querySelector("a")?.getAttribute("href");
  const img = cooked.querySelector("img");
  const thumbnail = img?.getAttribute("src");
  const dominantColor = img?.dataset?.dominantColor;
  const title = cooked.dataset.videoTitle;
  const startTime = cooked.dataset.videoStartTime;
  const listId = cooked.dataset.videoListId;
  const providerName = cooked.dataset.providerName;
  const id = cooked.dataset.videoId;

  return {
    url,
    thumbnail,
    title,
    providerName,
    id,
    dominantColor,
    startTime,
    listId,
  };
}
import { withPluginApi } from "discourse/lib/plugin-api";
import LazyVideo from "../discourse/components/lazy-video.gjs";
import getVideoAttributes from "../lib/lazy-video-attributes.js";

function initLazyEmbed(api) {
  api.decorateCookedElement(
    (cooked, helper) => {
      if (cooked.classList.contains("d-editor-preview")) {
        return;
      }

      const lazyContainers = cooked.querySelectorAll(".lazy-video-container");

      lazyContainers.forEach((container) => {
        const siteSettings = api.container.lookup("service:site-settings");
        const videoAttributes = getVideoAttributes(container);

        if (siteSettings[`lazy_${videoAttributes.providerName}_enabled`]) {
          const onLoadedVideo = () => {
            const postId = cooked.closest("article")?.dataset?.postId;
            if (postId) {
              api.preventCloak(parseInt(postId, 10));
            }
          };

          const lazyVideo = document.createElement("p");
          lazyVideo.classList.add("lazy-video-wrapper");

          helper.renderGlimmer(
            lazyVideo,
            <template>
              <LazyVideo
                @onLoadedVideo={{@data.onLoadedVideo}}
                @videoAttributes={{@data.param}}
              />
            </template>,
            { param: videoAttributes, onLoadedVideo }
          );

          container.replaceWith(lazyVideo);
        }
      });
    },
    { onlyStream: true }
  );
}

export default {
  name: "discourse-lazy-videos",

  initialize() {
    withPluginApi(initLazyEmbed);
  },
};
import * as Mod1 from "./discourse/components/lazy-iframe";
import * as Mod2 from "./discourse/components/lazy-video";
import * as Mod3 from "./discourse/initializers/lazy-videos-admin-plugin-configuration-nav";
import * as Mod4 from "./initializers/lazy-videos";
import * as Mod5 from "./lib/lazy-video-attributes";
const compatModules = {
  "discourse/components/lazy-iframe": Mod1,
  "discourse/components/lazy-video": Mod2,
  "discourse/initializers/lazy-videos-admin-plugin-configuration-nav": Mod3,
  "initializers/lazy-videos": Mod4,
  "lib/lazy-video-attributes": Mod5,
};
export { compatModules };
export default compatModules;
